import React from "react";

function Syntex() {
  const age = 18;

  return (
    <div>
      {/* Conditional Rendering */}

      {age >= 18 ? (
        <h2>You are eligible to vote ✅</h2>
      ) : (
        <h2>You are not eligible to vote </h2>
      )}
    </div>
  );
}

export default Syntex;
